import { ButtonType, type GameContext, type IGameMode, type IPpuApi } from "../../src/types/plugin";
import { BlockData, BlockType, drawBlock, StageData } from "./data";
import { stageLoader, StagePlayMode, type StageMode } from "./stage";

const BLOCK_CHARA = " OX#~V!$EP";

class EditMode implements IGameMode {
    private width: number;
    private height: number;
    private data: BlockData[][];
    private selPos = {
        x: 0,
        y: 0,
        count: 0
    };
    private stageMode: StageMode;
    private scrollPos = {
        x: 0,
        y: 0,
        maxX: 0,
        maxY: 0
    };
    private command = {
        index: -1,
        stage: [1, 1, 1]
    };
    private editStage: string[] = [];

    public constructor(width: number, height: number, mode: StageMode) {
        this.width = width;
        this.height = height;
        this.stageMode = mode;
        this.scrollPos.maxX = Math.max(0, this.width - 13);
        this.scrollPos.maxY = Math.max(0, this.height - 12);
        this.data = this.makeBlock([]);
    }
    private makeBlock(data: string[]): BlockData[][] {
        const maxwd = Math.max(...data.map(v => v.length));
        let marginX = 0;
        let offsetY = Math.max(0, data.length - this.height);
        if (maxwd < this.width) {
            marginX = Math.floor((this.width - maxwd) / 2);
        }
        let block: BlockData[][] = [];
        for (let y = 0; y < this.height; y++) {
            let line: BlockData[] = [];
            let dtstr = data[y + offsetY];
            for (let x = 0; x < this.width; x++) {
                if (x < marginX || !dtstr || x - marginX >= dtstr.length) {
                    line.push(new BlockData(" "));
                } else {
                    const ch = dtstr.charAt(x - marginX);
                    const blk = new BlockData(ch);
                    blk.setOrgBlock(BLOCK_CHARA.indexOf(ch)).setCharaIndex(BLOCK_CHARA.indexOf(ch));
                    line.push(blk);
                }
            }
            block.push(line);
        }
        return block;
    }
    onEnter(context: GameContext, _prev?: IGameMode): void {
        void (async () => {
            // エディットデータの読み込み
            let data:string[] = [];
            for (let i = 0; i < 5; i++) {
                const text = await context.util.getSaveData<string>([this.stageMode, i + 1]);
                data.push(text || "");
            }
            this.editStage = data;
        })();
        context.ppu.setControllData({
            bgClippingDisabled: false,
            bgEnabled: true,
            spriteClippingDisabled: false,
            spriteEnabled: true,
        });
        context.ppu.getPalette().write(16, 15);
        context.ppu.setScroll(0, 0);
        for (let i = 0; i < 64; i++) {
            context.ppu.setSpriteData({
                index: i,
                y: 239
            });
        }
        this.draw(context.ppu, this.data, true);
    }
    onResume(context: GameContext, prev?: IGameMode): void {
        this.onEnter(context, prev);
    }
    private draw(ppu: IPpuApi, data: BlockData[][], force: boolean): void {
        if (force) {
            for (let y = 0; y < this.height + 2; y++) {
                drawBlock(ppu, 0, y, BlockType.STONE);
                drawBlock(ppu, this.width + 1, y, BlockType.STONE);
            }
            for (let x = 0; x < this.width; x++) {
                drawBlock(ppu, x + 1, 0, BlockType.SPACE);
                drawBlock(ppu, x + 1, this.height + 1, BlockType.STONE);
            }
        }
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                if (x === this.selPos.x && y === this.selPos.y && (this.selPos.count & 32) === 0) {
                    drawBlock(ppu, x + 1, y + 1, -1);
                } else {
                    data[y][x].draw(ppu, x + 1, y + 1, force);
                }
            }
        }
        ppu.setScroll(this.scrollPos.x * 16, this.scrollPos.y * 16);
    }
    private printText(ppu: IPpuApi, text: string, x: number, y: number): void {
        let nmix = 0;
        let bx = x + this.scrollPos.x * 2;
        let by = y + this.scrollPos.y * 2;
        if (by >= 30) {
            by -= 30;
            nmix = 2;
        }
        for (let i = 0; i < text.length; i++) {
            if (bx >= 32) {
                bx -= 32;
                nmix ^= 1;
            }
            ppu.getNameTable(nmix).print(bx, by, text.charAt(i)).setColor(bx, by, 0);
            bx++;
        }
    }
    private drawCommand(ppu: IPpuApi, data: BlockData[][]): void {
        this.draw(ppu, data, true);
        let sel = [" ", " ", " "];
        sel[this.command.index] = ":";
        let stg = ["EDIT " + this.command.stage[0], "EDIT " + this.command.stage[1], "STAGE " + this.command.stage[2]];
        if (stg[2].length === 7) {
            stg[2] += " ";
        }
        this.printText(ppu, "______________", 8, 8);
        this.printText(ppu, "_            _", 8, 9);
        this.printText(ppu, "_ SAVE STAGE _", 8, 10);
        this.printText(ppu, "_            _", 8, 11);
        this.printText(ppu, "_  " + sel[0] + stg[0] + "   _", 8, 12);
        this.printText(ppu, "_            _", 8, 13);
        this.printText(ppu, "_ LOAD STAGE _", 8, 14);
        this.printText(ppu, "_            _", 8, 15);
        this.printText(ppu, "_  " + sel[1] + stg[1] + "   _", 8, 16);
        this.printText(ppu, "_  " + sel[2] + stg[2] + " _", 8, 17);
        this.printText(ppu, "_            _", 8, 18);
        this.printText(ppu, "______________", 8, 19);
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        if (this.command.index >= 0) {
            // 特別
            if (pad.isPush(ButtonType.SELECT)) {
                this.draw(context.ppu, this.data, true);
                this.command.index = -1;
                return;
            } else if (pad.isPush(ButtonType.START)) {
                // 確定
                if (this.command.index === 0) {
                    // 書き込み
                    const text = this.makeStageText().join('\n');
                    context.util.setSaveData([this.stageMode, this.command.stage[0]], text);
                    this.editStage[this.command.stage[0] - 1] = text;
                } else if (this.command.index === 1) {
                    // エディットステージを読み込む
                    this.data = this.makeBlock((this.editStage[this.command.stage[1] - 1] || "").split('\n'));
                } else if (this.command.index === 2) {
                    // 読み込み
                    const stg = stageLoader.getStage(this.stageMode, this.command.stage[2])!;
                    this.data = this.makeBlock(stg.data);
                }
                this.draw(context.ppu, this.data, true);
                this.command.index = -1;
                return;
            }
            let index = this.command.index;
            let stage = this.command.stage[index];
            if (pad.isPush(ButtonType.UP)) {
                index = (index + 2) % 3;
                stage = this.command.stage[index];
            } else if (pad.isPush(ButtonType.DOWN)) {
                index = (index + 1) % 3;
                stage = this.command.stage[index];
            } else if (pad.isPush(ButtonType.LEFT)) {
                stage--;
            } else if (pad.isPush(ButtonType.RIGHT)) {
                stage++;
            }
            if (index !== this.command.index || stage !== this.command.stage[index]) {
                this.command.index = index;
                let maxStage = 5;
                if (index === 2) {
                    maxStage = stageLoader.getStageCount(this.stageMode);
                }
                stage = ((stage + maxStage - 1) % maxStage) + 1;
                this.command.stage[index] = stage;
                let data = this.data;
                if (index === 1) {
                    // エディットステージを読み込む
                    data = this.makeBlock((this.editStage[stage - 1] || "").split('\n'));
                } else if (index === 2) {
                    // ステージを読み込む
                    const stg = stageLoader.getStage(this.stageMode, stage)!;
                    data = this.makeBlock(stg.data);
                }
                this.drawCommand(context.ppu, data);
            }
            return;
        }
        this.selPos.count++;
        const blk = this.data[this.selPos.y][this.selPos.x];
        blk.redraw();
        if (this.selPos.y > 0 && pad.isPush(ButtonType.UP)) {
            this.selPos.y--;
            this.selPos.count = 0;
        } else if (this.selPos.y < this.height - 1 && pad.isPush(ButtonType.DOWN)) {
            this.selPos.y++;
            this.selPos.count = 0;
        } else if (this.selPos.x > 0 && pad.isPush(ButtonType.LEFT)) {
            this.selPos.x--;
            this.selPos.count = 0;
        } else if (this.selPos.x < this.width - 1 && pad.isPush(ButtonType.RIGHT)) {
            this.selPos.x++;
            this.selPos.count = 0;
        } else if (pad.isPush(ButtonType.A)) {
            let b = blk.getOrgBlock();
            b = (b + 1) % 10;
            blk.setOrgBlock(b).setCharaIndex(b);
            this.selPos.count = 32;
        } else if (pad.isPush(ButtonType.B)) {
            let b = blk.getOrgBlock();
            b = (b + 9) % 10;
            blk.setOrgBlock(b).setCharaIndex(b);
            this.selPos.count = 32;
        } else if (pad.isPush(ButtonType.START)) {
            const stage = this.makeStage();
            stage.initStage();
            stage.drawStage(context.ppu, true);
            context.pushMode(new StagePlayMode(stage));
            return;
        } else if (pad.isPush(ButtonType.SELECT)) {
            this.command.index = 0;
            this.selPos.count = 32;
            this.drawCommand(context.ppu, this.data);
            return;
        }
        if (this.scrollPos.x > 0 && (this.selPos.x - this.scrollPos.x) < 2) {
            this.scrollPos.x--;
        } else if (this.scrollPos.x < this.scrollPos.maxX - 1 && (this.selPos.x - this.scrollPos.x) > 11) {
            this.scrollPos.x++;
        }
        if (this.scrollPos.y > 0 && (this.selPos.y - this.scrollPos.y) < 2) {
            this.scrollPos.y--;
        } else if (this.scrollPos.y < this.scrollPos.maxY - 1 && (this.selPos.y - this.scrollPos.y) > 10) {
            this.scrollPos.y++;
        }
        this.draw(context.ppu, this.data, false);
    }
    private makeStageText(): string[] {
        let data: string[] = [];
        for (let y = 0; y < this.height; y++) {
            let dt = "";
            for (let x = 0; x < this.width; x++) {
                const blk = this.data[y][x].getOrgBlock();
                dt += BLOCK_CHARA.charAt(blk);
            }
            data.push(dt);
        }
        return data;
    }
    private makeStage(): StageData {
        let data = this.makeStageText();
        if (data.length < 14) {
            // 一番上に脱出はしごをつける
            let dt = "";
            for (let x = 0; x < this.width; x++) {
                if (data[0][x] === '!') {
                    dt += "!";
                } else {
                    dt += " ";
                }
            }
            data = [dt, ...data];
        }
        const st = stageLoader.getStage(this.stageMode, 1)!;
        return new StageData(data, st.config);
    }
}

const editTypeList: {
    width: number;
    height: number;
    mode: StageMode;
}[] = [
        {
            width: 14,
            height: 13,
            mode: "tsume"
        },
        {
            width: 28,
            height: 13,
            mode: "loderun"
        },
        {
            width: 28,
            height: 16,
            mode: "champ"
        }
    ];
export class EdditSelect implements IGameMode {
    private selMode = 0;

    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setControllData({
            bgClippingDisabled: false,
            bgEnabled: true,
            spriteClippingDisabled: false,
            spriteEnabled: false
        });
        context.ppu.getPalette().write(16, 15);
        context.ppu.setScroll(0, 0);
        for (let y = 0; y < 15; y++) {
            for (let x = 0; x < 16; x++) {
                drawBlock(context.ppu, x, y, BlockType.SPACE);
            }
        }
        this.draw(context.ppu);
    }
    private draw(ppu: IPpuApi): void {
        const name = ppu.getNameTable(0);
        name.print(11, 10, "STAGE SIZE");
        for (let i = 0; i < editTypeList.length; i++) {
            const tp = editTypeList[i];
            let sel = (this.selMode === i) ? ":" : " ";
            name.print(12, i * 2 + 12, sel + tp.width + " X " + tp.height);
        }
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        let sel = this.selMode;
        const pad = context.getPad(0)!;
        if (pad.isPush(ButtonType.UP)) {
            sel = (sel + editTypeList.length - 1) % editTypeList.length;
        } else if (pad.isPush(ButtonType.DOWN) || pad.isPush(ButtonType.SELECT)) {
            sel = (sel + 1) % editTypeList.length;
        } else if (pad.isPush(ButtonType.START)) {
            const type = editTypeList[this.selMode];
            context.moveMode(new EditMode(type.width, type.height, type.mode));
            return;
        }
        if (this.selMode !== sel) {
            this.selMode = sel;
            this.draw(context.ppu);
        }
    }
}