import { ButtonType, type GameContext, type IGameMode, type IPpuApi } from '../../src/types/plugin'
import { EdditSelect } from './edit';
import { StageStartMode } from './stage';

abstract class TitlePlayBase implements IGameMode {
  private command: {
    x: number;
    y: number;
    size: number;
    select: number;
  } = {
      x: 0,
      y: 0,
      size: 0,
      select: 0
    };
  protected highScore: {
    [key: string]: number;
  } = {
    "loderun": 0,
    "champ": 0,
    "tsume": 0
  };
  onEnter(context: GameContext, _prev?: IGameMode): void {
    context.util.getSaveData<number>(["highScore", "loderun"]).then((data) => {
      this.highScore.loderun = data ?? 0;
    });
    context.util.getSaveData<number>(["highScore", "champ"]).then((data) => {
      this.highScore.champ = data ?? 0;
    });
    context.util.getSaveData<number>(["highScore", "tsume"]).then((data) => {
      this.highScore.tsume = data ?? 0;
    });
    const nameTable = context.ppu.getNameTable(0);
    context.ppu.setScroll(0, 0);
    context.ppu.setControllData({
      bgEnabled: true,
      spriteEnabled: false,
      nameTableIndex: 0,
      bgClippingDisabled: true,
      blueEmphasis: false,
      redEmphasis: false,
      greenEmphasis: false
    });
    for (let i = 0; i < 0x3c0; i++) {
      nameTable.write(i, 0x60);
    }
    for (let i = 0x3c0; i < 0x3ff; i++) {
      nameTable.write(i, 0);
    }
    this.onInitTitle(context);
  }
  drawTitle(ppu: IPpuApi, sx: number, sy: number): void {
    const nameTable = ppu.getNameTable(0);
    for (let y = 0; y < 3; y++) {
      // title
      for (let x = 0; x < 22; x++) {
        nameTable.write(x + sx + (y + sy) * 32, ((x + y * 22 + 0xd0) & 255));
      }
    }
  }
  drawMark(ppu: IPpuApi, sx: number, sy: number): void {
    const nameTable = ppu.getNameTable(0);
    for (let y = 0; y < 3; y++) {
      // mark
      for (let x = 0; x < 5; x++) {
        nameTable.write(x + sx + (y + sy) * 32, ((x + y * 5 + 0x12) & 255));
      }
    }
  }
  drawCommand(ppu: IPpuApi, x: number, y: number, commands: string[]): void {
    const nameTable = ppu.getNameTable(0);
    for (let i = 0; i < commands.length; i++) {
      nameTable.print(x, y + i * 2, commands[i]);
    }
    this.command = {
      x: x - 1,
      y: y,
      size: commands.length,
      select: 0
    };
    nameTable.print(x - 1, y, ":");
  }
  onResume(context: GameContext, prev?: IGameMode): void {
    this.onEnter(context, prev);
  }
  onUpdate(context: GameContext, _deltaFrame: number): void {
    const pad = context.getPad(0)!;
    let sel = this.command.select;
    if (pad.isPush(ButtonType.START)) {
      this.onCommand(context, sel);
    } else if (pad.isPush(ButtonType.SELECT) || pad.isPush(ButtonType.DOWN)) {
      sel = (sel + 1) % this.command.size;
    } else if (pad.isPush(ButtonType.UP)) {
      sel = (sel + this.command.size - 1) % this.command.size;
    }
    if (sel !== this.command.select) {
      const nameTable = context.ppu.getNameTable(0);
      nameTable.print(this.command.x, this.command.y + this.command.select * 2, " ");
      this.command.select = sel;
      nameTable.print(this.command.x, this.command.y + this.command.select * 2, ":");
    }
  }
  abstract onInitTitle(context: GameContext): void;
  abstract onCommand(context: GameContext, command: number): void;
}
export class NormalTitlePlay extends TitlePlayBase {
  onInitTitle(context: GameContext): void {
    this.drawMark(context.ppu, 2, 5);
    this.drawTitle(context.ppu, 8, 5);
    const nameTable = context.ppu.getNameTable(0);
    for (let y = 11; y < 22; y++) {
      for (let x = 8; x < 24; x++) {
        if (y < 13 || y >= 20 || x < 10 || x >= 22) {
          nameTable.write(x + y * 32, 0x64 + ((x + y) & 1));
          nameTable.setColor(x, y, 1);
        }
      }
    }
    nameTable.print(2, 24, "COPYRIGHT @ 1984 HUDSON SOFT");
    nameTable.print(7, 25, "WITH PERMISSION OF");
    nameTable.print(4, 26, "BRODERBUND SOFTWARE INC");
    nameTable.print(7, 27, "ALL RIGHTS RESERVED");
    // 36, 87,239
    context.ppu.getPalette().write(0x10, 0x11);
    this.drawCommand(context.ppu, 12, 14, ["1 PLAYER", "EDIT MODE", "CHAMPION"]);
  }
  onCommand(context: GameContext, command: number): void {
    if (command === 0) {
      context.pushMode(new StageStartMode('loderun', 1, this.highScore["loderun"]));
    } else if (command === 1) {
      context.pushMode(new EdditSelect());
    } else if (command === 2) {
      context.moveMode(new ChampTitlePlay());
    }
  }
}
export class ChampTitlePlay extends TitlePlayBase {
  onInitTitle(context: GameContext): void {
    this.drawMark(context.ppu, 13, 4);
    this.drawTitle(context.ppu, 4, 12);
    const nameTable = context.ppu.getNameTable(0);
    for (let x = 0; x < 15; x++) {
      nameTable.write(0x108 + x, x + 0xc0);
      nameTable.write(0x128 + x, x + 0x21);
    }
    nameTable.print(2, 24, "COPYRIGHT 1984  DOUG SMITH");
    nameTable.print(3, 25, "PUBLISHED BY HUDSON SOFT");
    nameTable.print(6, 26, "UNDER LICENSE FROM");
    nameTable.print(3, 27, "BRODERBUND SOFTWARE INC");
    context.ppu.getPalette().write(0x10, 0x0f);
    this.drawCommand(context.ppu, 7, 17, ["PRESS START BUTTON", "TSUME RUNNER", "LODE RUNNER"]);
  }
  onCommand(context: GameContext, command: number): void {
    if (command === 0) {
      context.pushMode(new StageStartMode('champ', 1, this.highScore["champ"]));
    } else if (command === 1) {
      context.pushMode(new StageStartMode('tsume', 1, this.highScore["tsume"]));
    } else if (command === 2) {
      context.moveMode(new NormalTitlePlay());
    }
  }
}
