import { RomEntry, type GameContext, type IFamRom } from '../../src/types/plugin'
import memText from './memory.txt?raw';
import { NormalTitlePlay } from './title';

@RomEntry("ロードランナー", {
  text: "black",
  face: "#f0f0f0",
  side: "#f0f040"
})
// @ts-expect-error Registered by the RomEntry decorator.
class LodeRunner implements IFamRom {
  powerOn(context: GameContext): void {
    console.log("LodeRunner", context);
    context.ppu.setMirrorMode("fourScreen");
    let colorCount = 0;
    const color1 = [0x6, 0x16, 0x26, 0x16];
    const color2 = [0x20, 0x10, 0x00, 0x10];
    context.setVBlankListener(ppu => {
      colorCount++;
      const pal = ppu.getPalette();
      pal.write(9, color1[(colorCount >> 5) & 3]);
      pal.write(15, color2[(colorCount >> 4) & 3]);
    }, "color");

    const mem = context.util.parseMemoryText(memText);
    context.ppu.setControllData({
      bgEnabled: true,
      spriteEnabled: true,
      spriteClippingDisabled: true,
      bgClippingDisabled: true,
      bgPatternTableIndex: 1,
      spriteSize: 16
    });
    context.ppu.getPatternTable(0).writeBytes(0, mem.get('CHR1')!.subarray(0, 4096));
    context.ppu.getPatternTable(1).writeBytes(0, mem.get('CHR1')!.subarray(4096, 8192));

    const palette = context.ppu.getPalette();
    palette.writeBytes(0, new Uint8Array([
      0x0f, 0x16, 0x30, 0x38, 0x0f, 0x17, 0x26, 0x07,
      0x0f, 0x36, 0x00, 0x30, 0x0f, 0x38, 0x28, 0x30,
      0x0f, 0x16, 0x27, 0x12, 0x0f, 0x30, 0x2b, 0x16,
      0x0f, 0x29, 0x16, 0x30, 0x0f, 0x30, 0x30, 0x30]));
    context.pushMode(new NormalTitlePlay());
  }
}
