import loderunStage from './stage/loderun.txt?raw';
import champStage from './stage/champ.txt?raw';
import tumeStage from './stage/tsume.txt?raw';
import clearStage from './stage/clear.txt?raw';
import { ButtonType, type GameContext, type IGameMode, type IPpuApi } from '../../src/types/plugin';
import { BlockType, drawBlock, StageData, type StageConfig } from './data';
import stageList from './stage/list.json';

export type StageMode = 'loderun' | 'champ' | 'tsume' | "clear";

interface GameState {
    score: number;
    highScore: number;
    resetPlayer: number;
}

/**
 * ステージテキストファイルをパースして、ステージデータを管理するクラス
 */
class StageLoader {
    private stages: Map<StageMode, string[][]> = new Map();

    constructor() {
        this.stages.set('loderun', this.parseStages(loderunStage));
        this.stages.set('champ', this.parseStages(champStage));
        this.stages.set('tsume', this.parseStages(tumeStage));
        this.stages.set('clear', this.parseStages(clearStage));
    }

    /**
     * テキストコンテンツをパースしてステージ配列に変換
     * @param content ステージテキスト（[1], [2]... で区切られている）
     * @returns ステージごとの文字列配列の配列
     */
    private parseStages(content: string): string[][] {
        const stages: string[][] = [];

        // [1], [2]... で分割
        const stageMatches = content.match(/\[\d+\]\n([\s\S]*?)(?=\n\[\d+\]|$)/g);

        if (!stageMatches) {
            return stages;
        }

        stageMatches.forEach((match) => {
            // [N] ヘッダーを削除して、ステージの本体を抽出
            let stageContent = match.replace(/^\[\d+\]\n/, '');

            // 末尾の改行と空行をすべて削除
            stageContent = stageContent.replace(/\n+$/, '');

            // 行ごとに分割して配列に
            const lines = stageContent.split('\n');
            stages.push(lines);
        });

        return stages;
    }

    /**
     * 指定されたモードとステージ番号でステージデータを取得
     * @param mode ステージモード（loderun, champ, tsume）
     * @param stageNumber ステージ番号（1から始まる）
     * @returns ステージの文字列配列、存在しない場合はundefined
     */
    getStage(mode: StageMode, stageNumber: number): {
        config: StageConfig;
        data: string[];
    } | undefined {
        const modeStages = this.stages.get(mode);
        if (!modeStages || stageNumber < 1 || stageNumber > modeStages.length || !stageList[mode]) {
            return undefined;
        }
        let config = Object.assign({
            "enemyHoleUpCount": 38,
            "enemyGoldCount": 128,
            "holeCount": [127, 40, 30, 20, 10],
            //"holeCharacter": [19, 19, 18, 17, 16, 15, 14, 13, 12, 12, 11, 10],
            "holeCharacter": [19, 18, 17, 16, 15, 14, 13, 12, 11, 10],
            "outBlock": BlockType.STONE,
            "moveFlag": "000000,010100,010101,010301,030301,030303,070303,070703,070707,0f0707,0f0f07,0f0f0f,1f0f0f,1f1f0f,1f1f1f,3f1f1f,3f3f1f,3f3f3f,7f3f3f,7f7f3f,7f7f7f",
            "offsetY": undefined,
            "runnerBoost": false,
        }, stageList[mode]);

        return {
            config: {
                enemyGoldCount: config.enemyGoldCount,
                enemyHoleUpCount: config.enemyHoleUpCount,
                holeCharacter: config.holeCharacter,
                holeCount: config.holeCount,
                outBlock: config.outBlock,
                enemyMoveFlag: config.moveFlag.split(",").map(v => parseInt(v, 16)),
                offestY: config.offsetY,
                runnerBoost: config.runnerBoost
            },
            data: modeStages[stageNumber - 1]
        };
    }

    /**
     * 指定されたモードの総ステージ数を取得
     * @param mode ステージモード
     * @returns ステージ数
     */
    getStageCount(mode: StageMode): number {
        return this.stages.get(mode)?.length ?? 0;
    }

    /**
     * 指定されたモードのすべてのステージを取得
     * @param mode ステージモード
     * @returns ステージ配列
     */
    getAllStages(mode: StageMode): string[][] {
        return this.stages.get(mode) ?? [];
    }
}

export const stageLoader = new StageLoader();

export class StageStartMode implements IGameMode {
    private mode: StageMode;
    private stage: number;
    private counter: number;
    private selMode: boolean;
    private state: GameState;

    public constructor(mode: StageMode, stage: number, highScore: number = 0) {
        this.mode = mode;
        this.stage = stage;
        this.counter = 0;
        this.selMode = false;
        this.state = {
            highScore: highScore,
            resetPlayer: 5,
            score: 0
        };
    }
    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setControllData({
            bgClippingDisabled: false,
            bgEnabled: true,
            spriteClippingDisabled: false,
            spriteEnabled: false
        });
        context.ppu.getPalette().write(16, 15);
        context.ppu.setScroll(0, 0);
        this.draw(context.ppu, true);
        this.counter = 3 * 60;
    }
    private draw(ppu: IPpuApi, score: boolean): void {
        for (let y = 0; y < 15; y++) {
            for (let x = 0; x < 16; x++) {
                drawBlock(ppu, x, y, BlockType.SPACE);
            }
        }
        const nameTable = ppu.getNameTable(0);
        nameTable.print(8, 14, "STAGE " + (new String(this.stage)).padStart(2, " "));
        if (!score) {
            return;
        }
        nameTable.print(12, 8, "PLAYER 1");
        nameTable.print(18, 14, "LEFT " + this.state.resetPlayer);
        nameTable.print(8, 18, "SCORE    " + (new String(this.state.score).padStart(8, "0")));
        nameTable.print(8, 20, "HISCORE  " + (new String(this.state.highScore).padStart(8, "0")));
    }
    onResume(context: GameContext, prev?: IGameMode): void {
        this.counter = 3 * 60;
        if (prev instanceof RunnerDead) {
            this.selMode = false;
            this.state.resetPlayer--;
            if (this.state.resetPlayer <= 0) {
                context.moveMode(new GameOverMode());
            }
        } else if (prev instanceof StagePlayMode) {
            // 選択
            this.selMode = true;
            this.onEnter(context, prev);
            this.draw(context.ppu, false);
            return;
        } else if (prev instanceof StageClearMode) {
            this.state.score += prev.getScore();
            if (this.state.score > this.state.highScore) {
                this.state.highScore = this.state.score;
                context.util.setSaveData(["highScore", this.mode], this.state.highScore).then();
            }
            const max = stageLoader.getStageCount(this.mode);
            this.stage = (this.stage % max) + 1;
            if (this.state.resetPlayer < 9) {
                this.state.resetPlayer++;
            }
        }
        this.onEnter(context, prev);
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        if (this.selMode) {
            let add = 0;
            if (pad.isPush(ButtonType.A) || pad.isPush(ButtonType.RIGHT)) {
                add = 1;
            } else if (pad.isPush(ButtonType.B) || pad.isPush(ButtonType.LEFT)) {
                add = -1;
            } else if (pad.isPush(ButtonType.UP)) {
                add = 10;
            } else if (pad.isPush(ButtonType.DOWN)) {
                add = -10;
            } else if (pad.isPush(ButtonType.START)) {
                this.selMode = false;
                this.draw(context.ppu, true);
                this.counter = 3 * 60;
                return;
            }
            if (add !== 0) {
                const max = stageLoader.getStageCount(this.mode);
                this.stage = (this.stage + add + max - 1) % max + 1;
                this.draw(context.ppu, false);
            }
            return;
        }
        if (pad.isPush(ButtonType.SELECT)) {
            this.selMode = true;
            this.draw(context.ppu, false);
            return;
        }
        this.counter--;
        if (this.counter > 0) {
            return;
        }
        const stageData = stageLoader.getStage(this.mode, this.stage);
        const data = new StageData(stageData!.data, stageData!.config);
        data.initStage();
        data.drawStage(context.ppu, true);
        context.pushMode(new StagePlayMode(data));
    }
}

const STEP_DEFAULT = 40;
const STEP_NEXT = 64;

export class StagePlayMode implements IGameMode {
    private stageData: StageData;
    private stepCounter: number;

    public constructor(stage: StageData) {
        this.stageData = stage;
        this.stepCounter = 0;
    }
    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setControllData({
            spriteEnabled: true
        });
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        if (pad.isPush(ButtonType.SELECT)) {
            context.exitMode();
        }
        if (this.stageData.getMode() !== "play") {
            this.stageData.stepFrame(pad);
            this.stageData.drawStage(context.ppu, false);
            return;
        }
        if (pad.isPush(ButtonType.START)) {
            context.pushMode(new StagePauseMode(this.stageData));
            return;
        }
        this.stepCounter += STEP_DEFAULT;
        while (this.stepCounter >= STEP_NEXT) {
            this.stepCounter -= STEP_NEXT;
            const result = this.stageData.stepFrame(pad);
            if (result === "dead") {
                context.moveMode(new RunnerDead(this.stageData));
                break;
            } else if (result === "clear") {
                context.moveMode(new StageClearMode(this.stageData));
                break;
            }
        }
        this.stageData.drawStage(context.ppu, false);
    }
}

class StagePauseMode implements IGameMode {
    private stage: StageData;
    constructor(stage: StageData) {
        this.stage = stage;
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        if (pad.isPush(ButtonType.START)) {
            this.stage.resume();
            context.exitMode();
            return;
        }
        if (pad.isDown(ButtonType.LEFT)) {
            this.stage.scrollLeft();
        }
        if (pad.isDown(ButtonType.RIGHT)) {
            this.stage.scrollRight();
        }
        if (pad.isDown(ButtonType.UP)) {
            this.stage.scrollUp();
        }
        if (pad.isDown(ButtonType.DOWN)) {
            this.stage.scrollDown();
        }
        this.stage.drawStage(context.ppu, false);
    }
}
class RunnerDead implements IGameMode {
    private stage: StageData;

    constructor(stage: StageData) {
        this.stage = stage;
    }

    onUpdate(context: GameContext, deltaFrame: number): void {
        if ((deltaFrame & 7) === 7) {
            this.stage.checkDead();
        }
        this.stage.drawStage(context.ppu, false);
        if (deltaFrame >= 180) {
            context.exitMode();
        }
    }
}
class StageClearMode implements IGameMode {
    private stage: StageData;
    private goldScore: number;
    private enemyScore: number;

    constructor(stage: StageData) {
        this.goldScore = stage.getPoint().gold;
        this.enemyScore = stage.getPoint().enemy;
        const dt = stageLoader.getStage("clear", 1)!;
        this.stage = new StageData(dt.data, dt.config);
    }

    public getScore(): number {
        return this.goldScore + this.enemyScore;
    }

    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setScroll(0, 0).setControllData({
            spriteEnabled: true
        });
        for (let i = 0; i < 64; i++) {
            context.ppu.setSpriteData({
                index: i,
                y: 239
            });
        }
        for (let y = 0; y < 15; y++) {
            for (let x = 0; x < 16; x++) {
                drawBlock(context.ppu, x, y, BlockType.SPACE);
            }
        }
        this.stage.initStage();
        const pos = this.stage.getPlayerPos();
        const blk = this.stage.getBlock(pos.x, pos.y);
        blk.setOrgBlock(BlockType.STEP);
        this.stage.drawStage(context.ppu, true);
        const nameTable = context.ppu.getNameTable(0);
        nameTable.print(14, 7, (new String(this.goldScore)).padStart(5, " ") + " POINTS");
        nameTable.print(14, 11, (new String(this.enemyScore)).padStart(5, " ") + " POINTS");
        nameTable.print(8, 19, "TOTAL " + (new String(this.goldScore + this.enemyScore)).padStart(5, " ") + " POINTS");
    }
    onUpdate(context: GameContext, deltaFrame: number): void {
        if ((deltaFrame & 7) === 0) {
            this.stage.clearStep();
        }
        this.stage.drawStage(context.ppu, false);
        if (deltaFrame >= 6 * 60 || context.getPad(0)!.isPush(ButtonType.START)) {
            context.exitMode();
        }
    }
}

class GameOverMode implements IGameMode {
    constructor() {

    }
    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setControllData({
            spriteEnabled: false
        }).setScroll(0, 0);
        const nameTable = context.ppu.getNameTable(0);
        for (let y = 0; y < 15; y++) {
            for (let x = 0; x < 15; x++) {
                drawBlock(context.ppu, x, y, BlockType.SPACE);
            }
        }
        nameTable.print(12, 8, "PLAYER 1");
        nameTable.print(11, 14, "GAME  OVER");
    }
    onUpdate(context: GameContext, deltaFrame: number): void {
        if (deltaFrame >= 200) {
            context.exitMode();
        }
    }
}