import { ButtonType, type IPadApi } from "../../src/types/plugin";
import { BlockData, BlockType, type StageConfig, type StageData } from "./data";

type MoveType = "MoveLeft" | "MoveRight" | "MoveUp" | "MoveDown" | "MoveFall" | "MoveNone" | "BeamLeft" | "BeamRight";
type IconType = "Walk" | "Bar" | "Fall" | "UpDown" | "Beam" | "BornDead" | "None" | "Hide" | "Clear";

class IconData {
    private iconType: IconType;
    private rightFlag: boolean;
    private iconIndex: number;

    public constructor() {
        this.iconType = "None";
        this.rightFlag = false;
        this.iconIndex = 0;
    }
    public setIcon(type: IconType): IconData {
        if (type !== this.iconType) {
            this.iconType = type;
            this.iconIndex = 0;
        } else {
            // アニメーションする
            this.iconIndex++;
        }
        return this;
    }
    public getIconType(): IconType {
        return this.iconType;
    }
    public getIconIndex(): number {
        return this.iconIndex;
    }
    public isRightFlag(): boolean {
        return this.rightFlag;
    }

    public setRightFlag(flag: boolean): IconData {
        this.rightFlag = flag;
        return this;
    }
}

abstract class SpriteData {
    protected blockX: number;
    protected blockY: number;
    // 3が中央、0-7
    protected subX: number;
    protected subY: number;

    protected iconData: IconData;
    private iconDataMap: Map<IconType, number[]>;

    private spriteBlock: number;

    protected constructor(bx: number, by: number, block: number) {
        this.blockX = bx;
        this.blockY = by;
        this.spriteBlock = block;
        this.subX = this.subY = 3;
        this.iconDataMap = new Map();
        this.iconData = new IconData();
    }
    protected entryIcon(type: IconType, data: number[]): void {
        this.iconDataMap.set(type, data);
    }
    protected canMoveBlock(block: BlockData, mv: MoveType): boolean {
        const curBlock = block.getCurBlock();
        if (curBlock === BlockType.ENEMY && this.spriteBlock === BlockType.ENEMY) {
            return false;
        }
        if (curBlock === BlockType.BLOCK || curBlock === BlockType.STONE) {
            return false;
        }
        if (block.getOrgBlock() === BlockType.TRAP && mv !== "MoveDown" && mv !== "MoveFall") {
            return false;
        }
        return true;
    }
    protected canMove(stage: StageData, mv: MoveType): boolean {
        switch (mv) {
            case "MoveLeft":
                if (this.subX > 3) {
                    return true;
                } else if (this.canMoveBlock(stage.getBlock(this.blockX - 1, this.blockY), mv)) {
                    return true;
                }
                break;
            case "MoveRight":
                if (this.subX < 3) {
                    return true;
                } else if (this.canMoveBlock(stage.getBlock(this.blockX + 1, this.blockY), mv)) {
                    return true;
                }
                break;
            case "MoveUp":
                if (this.subY > 3) {
                    return true;
                } else if (this.canMoveBlock(stage.getBlock(this.blockX, this.blockY - 1), mv)) {
                    const blk = stage.getBlock(this.blockX, this.blockY);
                    if (blk.getOrgBlock() === BlockType.STEP || blk.getCurBlock() === BlockType.ENEMY) {
                        return true;
                    }
                }
                break;
            case "MoveDown":
            case "MoveFall":
                if (this.subY < 3) {
                    return true;
                } else if (this.canMoveBlock(stage.getBlock(this.blockX, this.blockY + 1), mv)) {
                    return true;
                }
                break;
            case "BeamLeft":
                if (stage.getBlock(this.blockX - 1, this.blockY + 1).getCurBlock() === BlockType.BLOCK
                    && stage.getBlock(this.blockX - 1, this.blockY).getCurBlock() === BlockType.SPACE) {
                    return true;
                }
                break;
            case "BeamRight":
                if (stage.getBlock(this.blockX + 1, this.blockY + 1).getCurBlock() === BlockType.BLOCK
                    && stage.getBlock(this.blockX + 1, this.blockY).getCurBlock() === BlockType.SPACE) {
                    return true;
                }
                break;
        }
        return false;
    }
    public moveTo(stage: StageData, ...mv: MoveType[]): MoveType {
        let result: MoveType = "MoveNone";
        if (this.isFall(stage)) {
            // 落ちる
            result = "MoveFall";
        } else if (mv.includes("BeamLeft") && this.canMove(stage, "BeamLeft")) {
            result = "BeamLeft";
        } else if (mv.includes("BeamRight") && this.canMove(stage, "BeamRight")) {
            result = "BeamRight";
        } else if (mv.includes("MoveUp") && this.canMove(stage, "MoveUp")) {
            result = "MoveUp";
        } else if (mv.includes("MoveDown") && this.canMove(stage, "MoveDown")) {
            result = "MoveDown";
        } else if (mv.includes("MoveLeft") && this.canMove(stage, "MoveLeft")) {
            result = "MoveLeft";
        } else if (mv.includes("MoveRight") && this.canMove(stage, "MoveRight")) {
            result = "MoveRight";
        }

        let nx = this.subX;
        let ny = this.subY;
        let bx = this.blockX;
        let by = this.blockY;
        // 下移動は若干早い
        const downLimit = 6;
        let rightLimit = 7;
        let leftStart = 7;
        // チャンピオンシップは上への移動も早く感じる
        let upStart = 7;
        if (this.spriteBlock === BlockType.PLAYER && stage.conifg.runnerBoost) {
            rightLimit = 6;
            leftStart = 6;
            upStart = 6;
        }
        const blk = stage.getBlock(bx, by);
        const barFlag = (this.subY === 3 && blk.getOrgBlock() === BlockType.BAR);
        switch (result) {
            case "MoveLeft":
                if (nx > 0) {
                    nx--;
                } else {
                    nx = leftStart;
                    bx--;
                }
                this.iconData.setIcon(barFlag ? "Bar" : "Walk").setRightFlag(false);
                break;
            case "MoveRight":
                if (nx < rightLimit) {
                    nx++;
                } else {
                    nx = 0;
                    bx++;
                }
                this.iconData.setIcon(barFlag ? "Bar" : "Walk").setRightFlag(true);
                break;
            case "MoveUp":
                if (ny > 0) {
                    ny--;
                } else {
                    ny = upStart;
                    by--;
                }
                this.iconData.setIcon("UpDown");
                break;
            case "MoveDown":
                if (ny < downLimit) {
                    ny++;
                } else {
                    ny = 0;
                    by++;
                }
                this.iconData.setIcon("UpDown");
                break;
            case "MoveFall":
                if (ny < downLimit) {
                    ny++;
                } else {
                    ny = 0;
                    by++;
                }
                this.iconData.setIcon("Fall");
                break;
            case "BeamLeft":
                if (this.iconData.getIconType() === "UpDown") {
                    // はしごでビーム
                    this.iconData.setIcon("UpDown");
                } else {
                    this.iconData.setIcon(barFlag ? "Bar" : "Beam").setRightFlag(false);
                }
                break;
            case "BeamRight":
                if (this.iconData.getIconType() === "UpDown") {
                    // はしごでビーム
                    this.iconData.setIcon("UpDown");
                } else {
                    this.iconData.setIcon(barFlag ? "Bar" : "Beam").setRightFlag(true);
                }
                break;
        }
        if (result !== "MoveNone") {
            if (nx !== 3 && nx === this.subX) {
                // 左右の調整
                nx += Math.sign(3 - nx);
            }
            if (ny !== 3 && ny === this.subY) {
                // 上下の調整
                ny += Math.sign(3 - ny);
            }
        }
        this.subX = nx;
        this.subY = ny;
        if (bx !== this.blockX || by !== this.blockY) {
            if (blk.getOrgBlock() === BlockType.BLOCK) {
                // 空白にする
                blk.setCurBlock(BlockType.SPACE);
            } else {
                blk.setCurBlock(blk.getOrgBlock());
            }
            this.blockMoved(bx, by, this.blockX, this.blockY, stage);
            stage.getBlock(bx, by).setCurBlock(this.spriteBlock);
            // 移動した直後に落ちるかも
            //let samey = (this.blockY === by);
            this.blockX = bx;
            this.blockY = by;
            /*
            if (samey && this.isFall(stage)) {
                this.subY++;
            }
            */
        }
        return result;
    }
    abstract blockMoved(newBx: number, newBy: number, oldBx: number, oldBy: number, stage: StageData): void;

    protected isFall(stage: StageData): boolean {
        const blk = stage.getBlock(this.blockX, this.blockY).getOrgBlock();
        if (blk === BlockType.STEP || (this.subY === 3 && blk === BlockType.BAR)) {
            return false;
        }
        if (this.subY < 3) {
            return true;
        }
        const down = stage.getBlock(this.blockX, this.blockY + 1).getCurBlock();
        return down !== BlockType.BLOCK && down !== BlockType.STONE && down !== BlockType.ENEMY && down !== BlockType.STEP;
    }
    public getSprite(): {
        x: number;
        y: number;
        tileIndex: number;
        horizontalFlip: boolean;
    }[] {
        const chara = (this.iconDataMap.get(this.iconData.getIconType()) || this.iconDataMap.get("Walk"))!;
        const ch = chara[this.iconData.getIconIndex() % chara.length] * 4;
        let x1 = this.blockX * 16 + this.subX * 2 - 6;
        let x2 = x1 + 8;
        let y = this.blockY * 16 + this.subY * 2 - 6;
        let reverse = !this.iconData.isRightFlag();
        if (!reverse) {
            [x1, x2] = [x2, x1];
        }
        return [{
            x: x1,
            y: y,
            tileIndex: ch,
            horizontalFlip: reverse
        }, {
            x: x2,
            y: y,
            tileIndex: ch + 2,
            horizontalFlip: reverse
        }];
    }
    public getBlockPos(): {
        x: number;
        y: number;
    } {
        return {
            x: this.blockX,
            y: this.blockY
        };
    }
    public getSpritePos(): {
        x: number;
        y: number;
    } {
        return {
            x: this.blockX * 16 + this.subX * 2 - 6,
            y: this.blockY * 16 + this.subY * 2 - 6
        };
    }
}

const padMoveType: { [key: number]: MoveType; } = {
    [ButtonType.UP]: "MoveUp",
    [ButtonType.DOWN]: "MoveDown",
    [ButtonType.LEFT]: "MoveLeft",
    [ButtonType.RIGHT]: "MoveRight",
    [ButtonType.A]: "BeamRight",
    [ButtonType.B]: "BeamLeft"
};

export class PlayerData extends SpriteData {
    private beamCount: number;
    private lookCount: number;
    private holeCharacter: number[];

    public constructor(bx: number, by: number, config: StageConfig) {
        super(bx, by, BlockType.PLAYER);
        this.holeCharacter = config.holeCharacter;
        this.lookCount = 0;
        this.entryIcon("Walk", [0, 1, 2, 3]);
        this.entryIcon("Fall", [4, 5, 6, 7]);
        this.entryIcon("UpDown", [8, 9, 10, 11]);
        this.entryIcon("Bar", [12, 13, 14, 15]);
        this.entryIcon("Beam", [17]);
        this.entryIcon("None", [18, 19]);
        this.entryIcon("BornDead", [20, 21, 22, 23, 24, 25, 26, 27]);
        this.entryIcon("Clear", [60, 61, 62, 63]);
        this.beamCount = 0;
    }
    blockMoved(newBx: number, newBy: number, _oldBx: number, _oldBy: number, stage: StageData): void {
        if (stage.getBlock(newBx, newBy).getCurBlock() === BlockType.ENEMY) {
            // 死亡
            this.setDead();
        }
    }
    public setDead(): number {
        this.iconData.setIcon("BornDead");
        return this.iconData.getIconIndex();
    }
    public isDead(): boolean {
        return this.iconData.getIconType() === "BornDead";
    }
    private setHole(stage: StageData, bx: number, by: number, count: number): void {
        const blk = stage.getBlock(bx, by);
        if (count === 0) {
            stage.addHole(bx, by);
        } else if (count < 0) {
            // cancel
            blk.setCurBlock(BlockType.BLOCK).setCharaIndex(BlockType.BLOCK);
        } else {
            // 穴を掘っている
            blk.setCharaIndex(this.holeCharacter[count - 1]);
            if (this.subX !== 3) {
                this.subX += Math.sign(3 - this.subX);
            }
            if (this.subY !== 3) {
                this.subY += Math.sign(3 - this.subY);
            }
            this.checkGold(stage);
        }
    }
    private checkGold(stage: StageData): void {
        if (this.subX === 3 && this.subY === 3) {
            const blk = stage.getBlock(this.blockX, this.blockY);
            if (blk.getOrgBlock() === BlockType.GOLD) {
                // 取得
                blk.setOrgBlock(BlockType.SPACE).setCharaIndex(BlockType.SPACE);
                stage.gotGold(true);
            }
        }
    }
    moveCheck(stage: StageData, pad: IPadApi): void {
        if (this.beamCount < 0) {
            // 左に穴を掘っている
            if (this.canMove(stage, "BeamLeft")) {
                this.beamCount++;
                this.setHole(stage, this.blockX - 1, this.blockY + 1, -this.beamCount);
                return;
            } else {
                // Cancel
                this.beamCount = 0;
                this.setHole(stage, this.blockX - 1, this.blockY + 1, -1);
            }
        } else if (this.beamCount > 0) {
            // 右に穴を掘っている
            if (this.canMove(stage, "BeamRight")) {
                this.beamCount--;
                this.setHole(stage, this.blockX + 1, this.blockY + 1, this.beamCount);
                return;
            } else {
                // Cancel
                this.beamCount = 0;
                this.setHole(stage, this.blockX + 1, this.blockY + 1, -1);
            }
        }
        if (this.isFall(stage)) {
            this.moveTo(stage, "MoveFall");
            this.checkGold(stage);
            return;
        }
        let moveList: MoveType[] = [];
        for (let key in padMoveType) {
            if (pad.isDown(parseInt(key))) {
                moveList.push(padMoveType[key]);
            }
        }
        let result = this.moveTo(stage, ...moveList);
        if (result === "BeamLeft") {
            this.beamCount = -this.holeCharacter.length - 1;
        } else if (result === "BeamRight") {
            this.beamCount = this.holeCharacter.length + 1;
        } else if (result === "MoveNone") {
            const icon = this.iconData.getIconType();
            if (icon === "Fall") {
                if (stage.getBlock(this.blockX, this.blockY).getOrgBlock() === BlockType.BAR) {
                    this.iconData.setIcon("Bar");
                } else {
                    this.iconData.setIcon("None");
                }
            } else if (icon === "Walk" || icon === "None") {
                this.lookCount++;
                if (this.lookCount >= 20) {
                    this.iconData.setIcon("None");
                    this.lookCount = 0;
                }
            }
        }
        this.checkGold(stage);
    }
    public clearStep(stage: StageData): void {
        if (this.canMove(stage, "MoveUp")) {
            this.moveTo(stage, "MoveUp");
            return;
        }
        this.iconData.setIcon("Clear");
    }
}

export class EnemyData extends SpriteData {
    private static readonly HOLE_SWAY_COUNT = 13;
    private static readonly HOLE_ESCAPE_COUNT = 8;

    private goldCount: number;
    private holeUpCount: number;
    private waitFlag: boolean;
    private bornCount: number;

    private enemyUnderBlock = {
        orgBlock: BlockType.STONE,
        curBlock: BlockType.STONE
    };
    private enemyOutSideBlock = {
        orgBlock: BlockType.SPACE,
        curBlock: BlockType.SPACE
    };

    public constructor(bx: number, by: number) {
        super(bx, by, BlockType.ENEMY);
        this.entryIcon("Walk", [28, 29, 30, 31]);
        this.entryIcon("Fall", [32, 33, 34, 35]);
        this.entryIcon("UpDown", [36, 37, 38, 39]);
        this.entryIcon("Bar", [40, 41, 42, 43]);
        this.entryIcon("BornDead", [44, 45, 46, 47]);
        this.goldCount = 0;
        this.holeUpCount = 0;
        this.waitFlag = false;
        this.bornCount = 0;
    }
    public moveTo(stage: StageData, ...mv: MoveType[]): MoveType {
        const res = super.moveTo(stage, ...mv);
        if (this.goldCount > 1 && res !== 'MoveNone') {
            this.goldCount--;
        }
        return res;
    }
    blockMoved(newBx: number, newBy: number, oldBx: number, oldBy: number, stage: StageData): void {
        if (stage.getBlock(newBx, newBy).getCurBlock() === BlockType.PLAYER) {
            // プレイヤー死亡
            return;
        }
        if (this.goldCount === 1 || (this.goldCount > 1 && stage.randomInt(16) === 0)) {
            const blk = stage.getBlock(oldBx, oldBy);
            if (blk.getOrgBlock() === BlockType.SPACE && this.iconData.getIconType() !== "Fall") {
                blk.setOrgBlock(BlockType.GOLD).setCurBlock(BlockType.GOLD).setCharaIndex(BlockType.GOLD);
                this.goldCount = 0;
            }
        }
        if (newBy > oldBy) {
            const blk = stage.getBlock(newBx, newBy);
            if (blk.getOrgBlock() === BlockType.BLOCK && blk.getCurBlock() === BlockType.SPACE) {
                // 穴に埋まった
                this.holeUpCount = stage.conifg.enemyHoleUpCount + EnemyData.HOLE_ESCAPE_COUNT;
                this.waitFlag = true;
                if (this.goldCount > 0) {
                    const blk2 = stage.getBlock(oldBx, oldBy);
                    if (blk2.getOrgBlock() === BlockType.SPACE) {
                        blk2.setOrgBlock(BlockType.GOLD).setCurBlock(BlockType.GOLD).setCharaIndex(BlockType.GOLD);
                    } else {
                        stage.gotGold(false);
                    }
                    this.goldCount = 0;
                }
                return;
            }
        }
        if (this.holeUpCount > 0 && oldBx === newBx && oldBy === newBy + 1) {
            // 穴から這い上がれたのでしばらく落ちないようにする
            this.holeUpCount = 6;
        }
        this.waitFlag = false;
    }
    protected isFall(stage: StageData): boolean {
        if (this.holeUpCount > 0 && this.holeUpCount <= EnemyData.HOLE_ESCAPE_COUNT) {
            return false;
        }
        return super.isFall(stage);
    }
    checkMove(stage: StageData): void {
        if (this.bornCount > 0) {
            if (stage.getBlock(this.blockX, this.blockY).getCurBlock() !== BlockType.SPACE) {
                return;
            }
            if ((this.bornCount & 3) === 0) {
                this.iconData.setIcon("BornDead");
            }
            this.bornCount--;
            if (this.bornCount === 0) {
                this.waitFlag = false;
                this.iconData.setIcon("Fall");
                stage.getBlock(this.blockX, this.blockY).setCurBlock(BlockType.ENEMY);
            }
            return;
        }

        if (this.holeUpCount > 0) {
            this.holeUpCount--;
        }
        if (this.waitFlag) {
            if (this.holeUpCount === 0) {
                // 這い上がれなかった
                this.holeUpCount = stage.conifg.enemyHoleUpCount;
            } else if (this.holeUpCount <= EnemyData.HOLE_ESCAPE_COUNT) {
                this.subX = 3;
                this.moveTo(stage, "MoveUp");
            } else if (this.holeUpCount <= EnemyData.HOLE_SWAY_COUNT) {
                this.subX = 4 - ((this.holeUpCount & 1) * 2);
            } else if (this.subY < 3) {
                this.moveTo(stage, "MoveFall");
            }
            return;
        }
        if (this.isFall(stage)) {
            this.moveTo(stage, "MoveFall");
            this.tryPickupGold(stage);
            return;
        }

        const runner = stage.getPlayerPos();
        const mv = this.checkAdjoining(stage, runner);
        if (mv !== null) {
            this.stepMove(stage, mv);
            return;
        }
        const pointList = this.checkHorizontalArea(stage, runner);
        const pt = this.getPriorityPoint(pointList, runner);
        if (pt !== null) {
            if (pt.x < this.blockX) {
                this.stepMove(stage, "MoveLeft");
            } else if (pt.x > this.blockX) {
                this.stepMove(stage, "MoveRight");
            } else if (pt.y < this.blockY) {
                this.stepMove(stage, "MoveUp");
            } else {
                this.stepMove(stage, "MoveDown");
            }
            return;
        }
        this.stepMove(stage, "MoveDown");
    }
    private stepMove(stage: StageData, mv: MoveType): void {
        const result = this.moveTo(stage, mv);
        if (result !== "MoveNone") {
            this.tryPickupGold(stage);
        }
    }
    private tryPickupGold(stage: StageData): void {
        if (this.goldCount === 0 && this.subX === 3 && this.subY === 3) {
            const blk = stage.getBlock(this.blockX, this.blockY);
            if (blk.getOrgBlock() === BlockType.GOLD) {
                this.goldCount = Math.floor(Math.random() * stage.conifg.enemyGoldCount) + 3;
                blk.setOrgBlock(BlockType.SPACE).setCharaIndex(BlockType.SPACE);
            }
        }
    }
    setDead(stage: StageData): void {
        if (this.goldCount > 0) {
            // 金塊を持ったまま死んだ
            stage.gotGold(false);
            this.goldCount = 0;
        }
        this.bornCount = 15;
        this.waitFlag = true;
        this.holeUpCount = 0;
        this.iconData.setRightFlag(false);
        this.iconData.setIcon("BornDead");
        this.subX = 3;
        this.subY = 3;
        let bx = Math.floor(Math.random() * 28);
        let by = 1;
        for (let i = 0; i < 512; i++) {
            const blk = stage.getBlock(bx, by);
            if (blk.getOrgBlock() === BlockType.SPACE) {
                this.blockX = bx;
                this.blockY = by;
                return;
            }
            bx++;
            if (bx >= 32) {
                bx = 0;
                by++;
            }
        }
    }

    private checkAdjoining(stage: StageData, runner: { x: number; y: number }): MoveType | null {
        if (this.blockY !== runner.y) {
            return null;
        } else if (this.blockX === runner.x) {
            // 目的地
            return "MoveDown";
        }
        let bx = this.blockX;
        let ax = 1;
        if (runner.x < bx) {
            ax = -1;
        }
        bx += ax;
        while (bx !== runner.x) {
            switch (this.getBlockData(stage, bx, this.blockY + 1).orgBlock) {
                case BlockType.BLOCK:
                case BlockType.STONE:
                case BlockType.STEP:
                case BlockType.BAR:
                case BlockType.GOLD:
                    break;
                default: {
                    const blk = this.getBlockData(stage, bx, this.blockY).orgBlock;
                    if (blk !== BlockType.STEP && blk !== BlockType.BAR) {
                        return null;
                    }
                }
            }
            bx += ax;
        }
        return ax < 0 ? "MoveLeft" : "MoveRight";
    }

    private checkVerticalMovePoint(stage: StageData, bx: number, pointList: { x: number; y: number }[], runner: { x: number; y: number }): boolean {
        let retFlag = true;
        let blk = this.getBlockData(stage, bx, this.blockY);
        if (blk.curBlock === BlockType.BLOCK || blk.curBlock === BlockType.STONE) {
            return false;
        } else if (blk.curBlock !== BlockType.STEP && blk.curBlock !== BlockType.BAR) {
            const blk2 = this.getBlockData(stage, bx, this.blockY + 1);
            if (blk2.orgBlock !== BlockType.BLOCK
                && blk2.orgBlock !== BlockType.STONE
                && blk2.orgBlock !== BlockType.STEP) {
                retFlag = false;
            }
        }

        if (blk.orgBlock === BlockType.STEP) {
            let by = this.blockY - 1;
            while (this.getBlockData(stage, bx, by).orgBlock === BlockType.STEP) {
                if (this.getBlockData(stage, bx - 1, by).orgBlock === BlockType.BAR) {
                    pointList.push({ x: bx, y: by });
                } else if (this.getBlockData(stage, bx + 1, by).orgBlock === BlockType.BAR) {
                    pointList.push({ x: bx, y: by });
                } else {
                    const blk1 = this.getBlockData(stage, bx - 1, by + 1).orgBlock;
                    const blk2 = this.getBlockData(stage, bx + 1, by + 1).orgBlock;
                    if (blk1 === BlockType.BLOCK
                        || blk1 === BlockType.STONE
                        || blk1 === BlockType.STEP
                        || blk2 === BlockType.BLOCK
                        || blk2 === BlockType.STONE
                        || blk2 === BlockType.STEP) {
                        pointList.push({ x: bx, y: by });
                    }
                }
                by--;
            }
            pointList.push({ x: bx, y: by });
        }

        let by = this.blockY + 1;
        blk = this.getBlockData(stage, bx, by);
        let okFlag = false;
        while (by < 256 && blk.orgBlock !== BlockType.BLOCK && blk.orgBlock !== BlockType.STONE) {
            okFlag = false;
            if (by >= runner.y && blk.orgBlock !== BlockType.SPACE) {
                const blkL = this.getBlockData(stage, bx - 1, by);
                const blkR = this.getBlockData(stage, bx + 1, by);
                const blkLD = this.getBlockData(stage, bx - 1, by + 1);
                const blkRD = this.getBlockData(stage, bx + 1, by + 1);
                if (blkLD.orgBlock === BlockType.BLOCK
                    || blkLD.orgBlock === BlockType.STONE
                    || blkLD.orgBlock === BlockType.STEP
                    || blkRD.orgBlock === BlockType.BLOCK
                    || blkRD.orgBlock === BlockType.STONE
                    || blkRD.orgBlock === BlockType.STEP
                    || blkL.orgBlock === BlockType.BAR) {
                    okFlag = true;
                } else if (bx > 0 && blkRD.orgBlock === BlockType.BAR) {
                    okFlag = true;
                } else if (bx === 0 && blkR.orgBlock === BlockType.BAR) {
                    okFlag = true;
                }
            }
            if (okFlag) {
                pointList.push({ x: bx, y: by });
            }
            by++;
            blk = this.getBlockData(stage, bx, by);
        }
        if (!okFlag && by - 1 > this.blockY) {
            pointList.push({ x: bx, y: by - 1 });
        }
        return retFlag;
    }

    private checkHorizontalArea(stage: StageData, runner: { x: number; y: number }): { x: number; y: number }[] {
        const retList: { x: number; y: number }[] = [];
        this.checkVerticalMovePoint(stage, this.blockX, retList, runner);
        for (let bx = this.blockX - 1; bx >= 0; bx--) {
            if (!this.checkVerticalMovePoint(stage, bx, retList, runner)) {
                break;
            }
        }
        for (let bx = this.blockX + 1; bx < 64; bx++) {
            if (!this.checkVerticalMovePoint(stage, bx, retList, runner)) {
                break;
            }
        }
        return retList;
    }

    private getPriorityPoint(pointList: { x: number; y: number }[], runner: { x: number; y: number }): { x: number; y: number } | null {
        let ret: { x: number; y: number } | null = null;
        for (const pt of pointList) {
            if (pt.y === runner.y) {
                if (ret === null) {
                    ret = pt;
                } else {
                    const diff = Math.abs(ret.x - this.blockX) - Math.abs(pt.x - this.blockX);
                    if (diff > 0 || (diff === 0 && pt.x < ret.x)) {
                        ret = pt;
                    }
                }
            }
        }
        if (ret !== null) {
            return ret;
        }
        for (const pt of pointList) {
            if (ret === null) {
                ret = pt;
            } else if (ret.y === pt.y) {
                if (pt.x === this.blockX || (ret.x !== this.blockX && pt.x < ret.x)) {
                    ret = pt;
                }
            } else if (pt.y < runner.y) {
                if (ret.y > runner.y || pt.y > ret.y) {
                    ret = pt;
                }
            } else if (ret.y > runner.y && pt.y < ret.y) {
                ret = pt;
            }
        }
        return ret;
    }

    private getBlockData(stage: StageData, bx: number, by: number): {
        orgBlock: number;
        curBlock: number;
    } {
        if (by >= stage.getHeight()) {
            return this.enemyUnderBlock;
        }
        if (by < 0 || bx < 0 || bx >= stage.getWidth()) {
            // スペースとみなす
            return this.enemyOutSideBlock;
        }
        const blk = stage.getBlock(bx, by);
        return {
            orgBlock: blk.getOrgBlock(),
            curBlock: (bx === this.blockX && by === this.blockY) ? BlockType.SPACE : blk.getCurBlock()
        };
    }
}